SELECT f.id AS "ID do Arquivo", f.filename AS "Nome do Arquivo", f.filepath AS "Caminho do Arquivo", f.mimetype AS "Tipo do Arquivo", COUNT(CASE WHEN l.action = 'viewed' THEN 1 END) AS "Total de Visualizações", COUNT(CASE WHEN l.action = 'downloaded' THEN 1 END) AS "Total de Downloads", (COUNT(CASE WHEN l.action = 'viewed' THEN 1 END) + COUNT(CASE WHEN l.action = 'downloaded' THEN 1 END)) AS "Total de Interações" FROM mdl_files AS f LEFT JOIN mdl_logstore_standard_log AS l ON l.objectid = f.id WHERE l.target = 'file' AND f.filename <> '.' GROUP BY f.id, f.filename, f.filepath, f.mimetype ORDER BY "Total de Interações" DESC LIMIT 5;
